function MillstoneTenterHookMaker.init() MillstoneTenterHookMaker.ironStock=18; MillstoneTenterHookMaker.bronzeStock=14; MillstoneTenterHookMaker.woodStock=10; MillstoneTenterHookMaker.leatherStock=8; MillstoneTenterHookMaker.silverStock=8; MillstoneTenterHookMaker.goldStock=6; MillstoneTenterHookMaker.jewelStock=4; MillstoneTenterHookMaker.pearlStock=4; MillstoneTenterHookMaker.productStock={}; MillstoneTenterHookMaker.buildings={}; MillstoneTenterHookMaker.maker=nil; MillstoneTenterHookMaker.activeMaking={}; MillstoneTenterHookMaker.totalProducts=0; MillstoneTenterHookMaker.dayTimer=0; print("[MillstoneTenterHookMaker] Royal Millstone Tenter Hook Maker System initialized (6 products, 4 buildings)") end
function MillstoneTenterHookMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneTenterHookMaker.maker={name=n or ("Napenjalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napenjalec najet: %s (spretnost: %d)",MillstoneTenterHookMaker.maker.name,s),"success") end; return true end
function MillstoneTenterHookMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneTenterHookMaker.build(id) local ok,e=MillstoneTenterHookMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneTenterHookMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneTenterHookMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneTenterHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneTenterHookMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneTenterHookMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneTenterHookMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneTenterHookMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneTenterHookMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneTenterHookMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneTenterHookMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneTenterHookMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneTenterHookMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneTenterHookMaker.buildings==0 then return false,"Potrebna napenjalna delavnica" end; if not MillstoneTenterHookMaker.maker then return false,"Potreben napenjalec" end; return true end
function MillstoneTenterHookMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneTenterHookMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneTenterHookMaker.ironStock=MillstoneTenterHookMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneTenterHookMaker.bronzeStock=MillstoneTenterHookMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneTenterHookMaker.woodStock=MillstoneTenterHookMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneTenterHookMaker.leatherStock=MillstoneTenterHookMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneTenterHookMaker.silverStock=MillstoneTenterHookMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneTenterHookMaker.goldStock=MillstoneTenterHookMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneTenterHookMaker.jewelStock=MillstoneTenterHookMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneTenterHookMaker.pearlStock=MillstoneTenterHookMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneTenterHookMaker.maker then t=math.max(1,t-math.floor(MillstoneTenterHookMaker.maker.skill/13)) end; table.insert(MillstoneTenterHookMaker.activeMaking,{id="millstonetenterhook_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneTenterHookMaker.completeMaking(m) local q=1.0+(MillstoneTenterHookMaker.getQualityBonus()/100); if MillstoneTenterHookMaker.maker then q=q+(MillstoneTenterHookMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneTenterHookMaker.productStock[m.productType]=(MillstoneTenterHookMaker.productStock[m.productType] or 0)+m.quantity; MillstoneTenterHookMaker.totalProducts=MillstoneTenterHookMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneTenterHookMaker.maker then MillstoneTenterHookMaker.maker.itemsMade=MillstoneTenterHookMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneTenterHookMaker.maker.skill=math.min(100,MillstoneTenterHookMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kljuka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonetenterhook.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneTenterHookMaker.update(dt) if not _G.state then return end; MillstoneTenterHookMaker.dayTimer=MillstoneTenterHookMaker.dayTimer+dt; if MillstoneTenterHookMaker.dayTimer>=30 then MillstoneTenterHookMaker.dayTimer=0; for i=#MillstoneTenterHookMaker.activeMaking,1,-1 do local m=MillstoneTenterHookMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneTenterHookMaker.completeMaking(m); table.remove(MillstoneTenterHookMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneTenterHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneTenterHookMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneTenterHookMaker.getStats() return {ironStock=MillstoneTenterHookMaker.ironStock,bronzeStock=MillstoneTenterHookMaker.bronzeStock,woodStock=MillstoneTenterHookMaker.woodStock,leatherStock=MillstoneTenterHookMaker.leatherStock,silverStock=MillstoneTenterHookMaker.silverStock,goldStock=MillstoneTenterHookMaker.goldStock,jewelStock=MillstoneTenterHookMaker.jewelStock,pearlStock=MillstoneTenterHookMaker.pearlStock,productStock=MillstoneTenterHookMaker.productStock,numBuildings=#MillstoneTenterHookMaker.buildings,hasMaker=MillstoneTenterHookMaker.maker~=nil,makerName=MillstoneTenterHookMaker.maker and MillstoneTenterHookMaker.maker.name or "—",makerSkill=MillstoneTenterHookMaker.maker and MillstoneTenterHookMaker.maker.skill or 0,activeMaking=#MillstoneTenterHookMaker.activeMaking,totalProducts=MillstoneTenterHookMaker.totalProducts} end
